// Title: Export an Aspose.Cells workbook to HTML and confirm that leading apostrophes are preserved (C#)
// Common Searches: Aspose.Cells C# export worksheet to HTML keep leading apostrophe | how to verify apostrophe character in HTML generated by Aspose.Cells | C# check for &apos; entity after saving Excel as HTML with Aspose.Cells | preserve text prefix apostrophe when converting Excel to HTML using Aspose.Cells | Aspose.Cells SaveFormat.Html retain single quote in cell value
// Tags: Aspose.Cells HTML export preserve leading apostrophe | C# workbook SaveFormat.Html apostrophe handling | verify apostrophe in generated HTML Aspose.Cells | cell value text prefix export to HTML | Aspose.Cells HTML conversion text formatting

using System;
using System.IO;
using Aspose.Cells;

// The example creates a workbook, inserts a cell value prefixed with an apostrophe to force text format, saves the workbook as HTML using SaveFormat.Html, reads the resulting HTML file, and checks whether the leading apostrophe appears as a literal character or as an &apos; entity, reporting the verification result to the console.
class Program
{
    static void Main()
    {
        // Create a new workbook
        Workbook workbook = new Workbook();

        // Get the first worksheet
        Worksheet sheet = workbook.Worksheets[0];

        // Insert a value with a leading apostrophe
        // The apostrophe is used in Excel to force the cell to be treated as text
        sheet.Cells["A1"].PutValue("'Sample Text");

        // Define the output HTML file path
        string htmlFile = "WorkbookOutput.html";

        // Save the workbook as HTML
        workbook.Save(htmlFile, SaveFormat.Html);

        // Read the generated HTML content
        string htmlContent = File.ReadAllText(htmlFile);

        // Verify that the leading apostrophe is present in the rendered HTML
        // It may appear as a literal apostrophe or as an HTML entity (&apos;)
        if (htmlContent.Contains("'Sample Text") || htmlContent.Contains("&apos;Sample Text"))
        {
            Console.WriteLine("Leading apostrophe rendered correctly in HTML.");
        }
        else
        {
            Console.WriteLine("Leading apostrophe NOT found in HTML output.");
        }
    }
}
